   {"old": "// Los tipos de permiso de herramienta se importan de una ubicación
// centralizada para romper ciclos de import.
import type { ToolPermissionRulesBySource } from '@thyrox/permission/permissionTypes'

// Re-exporta por compatibilidad hacia atrás.
export type { ToolPermissionRulesBySource }",
    "new": "// Los tipos de permiso de herramienta se declaran localmente: la fuente
// centralizada (`@thyrox/permission/permissionTypes`) documenta a propósito
// que este tipo NO se porta ahí — cada consumidor declara su propia forma
// angosta (mismo patrón que ya usa `permissionSetup.ts`).
export type ToolPermissionRulesBySource = {
  [T in PermissionRuleSource]?: string[]
}"}
